from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        try:
            capacity = int(capacity_bytes)
        except Exception:
            capacity = 0
        self.capacity_bytes = max(0, capacity)
        self._items = {}
        self._probation = OrderedDict()
        self._protected = OrderedDict()
        self._ghosts = OrderedDict()
        self._ghost_limit = 4096
        self._bytes = 0
        self._protected_bytes = 0
        self._protected_target = (self.capacity_bytes * 2) // 3

    @staticmethod
    def _size_value(size):
        try:
            value = int(size)
        except Exception:
            value = 0
        return max(0, value)

    def _remember_ghost(self, key, segment):
        self._ghosts.pop(key, None)
        self._ghosts[key] = segment
        while len(self._ghosts) > self._ghost_limit:
            self._ghosts.popitem(last=False)

    def _remove(self, key, remember=True):
        record = self._items.pop(key, None)
        if record is None:
            return
        segment = record["segment"]
        if segment == "protected":
            self._protected.pop(key, None)
            self._protected_bytes -= record["size"]
        else:
            self._probation.pop(key, None)
        self._bytes -= record["size"]
        if remember:
            self._remember_ghost(key, segment)

    def _touch(self, key, segment):
        queue = self._protected if segment == "protected" else self._probation
        queue.pop(key, None)
        queue[key] = None

    def _promote(self, key):
        record = self._items[key]
        if record["segment"] == "protected":
            self._touch(key, "protected")
            return
        self._probation.pop(key, None)
        record["segment"] = "protected"
        self._protected[key] = None
        self._protected_bytes += record["size"]

    def _demote_oldest_protected(self):
        if not self._protected:
            return False
        key = next(iter(self._protected))
        record = self._items[key]
        self._protected.pop(key, None)
        self._protected_bytes -= record["size"]
        record["segment"] = "probation"
        self._probation[key] = None
        return True

    def _rebalance(self):
        while (
            self._protected
            and self._protected_bytes > self._protected_target
        ):
            if not self._demote_oldest_protected():
                break

    def _victim(self, excluded):
        for key in self._probation:
            if key != excluded:
                return key
        for key in self._protected:
            if key != excluded:
                return key
        return None

    def _make_room(self, excluded):
        evicted = []
        self._rebalance()
        while self._bytes > self.capacity_bytes:
            victim = self._victim(excluded)
            if victim is None:
                break
            evicted.append(victim)
            self._remove(victim, remember=True)
        return evicted

    def _adapt_target(self, ghost_segment):
        if self.capacity_bytes <= 0:
            return
        if ghost_segment == "probation":
            delta = max(
                1, (self.capacity_bytes - self._protected_target) // 8
            )
            self._protected_target = max(
                0, self._protected_target - delta
            )
        elif ghost_segment == "protected":
            delta = max(1, self._protected_target // 8)
            self._protected_target = min(
                self.capacity_bytes,
                self._protected_target + delta,
            )

    def access(self, key: int, size: int, now: int) -> list[int]:
        del now
        requested_size = self._size_value(size)

        if key in self._items:
            record = self._items[key]
            old_size = record["size"]
            record["size"] = requested_size
            self._bytes += requested_size - old_size

            if record["segment"] == "probation":
                self._promote(key)
            else:
                self._touch(key, "protected")

            if requested_size > self.capacity_bytes:
                self._remove(key, remember=True)
                return [key]
            return self._make_room(key)

        if self.capacity_bytes <= 0 or requested_size > self.capacity_bytes:
            return []

        ghost_segment = self._ghosts.pop(key, None)
        if ghost_segment is not None:
            self._adapt_target(ghost_segment)

        self._items[key] = {
            "size": requested_size,
            "segment": "probation",
        }
        self._probation[key] = None
        self._bytes += requested_size
        return self._make_room(key)
